<script setup lang="ts">import {ref,computed} from 'vue';import type {Point,GroupResult} from '../types/domain';import {num} from '../utils/format';import BoundaryShape from './BoundaryShape.vue';const props=defineProps<{points:Point[];result?:GroupResult;title?:string;compact?:boolean}>();const showPoints=ref(true),showHull=ref(true),showAxis=ref(true),showBox=ref(true);const bounds=computed(()=>{const all=props.points.map(p=>[p.x,p.y]);if(props.result)for(const o of [props.result.hull,props.result.axis_box,props.result.oriented_box])all.push(...(o.vertices||o.corners||[]));let x0=Math.min(...all.map(p=>p[0])),x1=Math.max(...all.map(p=>p[0])),y0=Math.min(...all.map(p=>p[1])),y1=Math.max(...all.map(p=>p[1]));const pad=Math.max(x1-x0,y1-y0,1)*.08;x0-=pad;x1+=pad;y0-=pad;y1+=pad;const scale=Math.min(850/(x1-x0),385/(y1-y0)),left=75+(850-(x1-x0)*scale)/2,top=35+(385-(y1-y0)*scale)/2;return {x0,x1,y0,y1,scale,left,top}});const sx=(x:number)=>bounds.value.left+(x-bounds.value.x0)*bounds.value.scale;const sy=(y:number)=>bounds.value.top+(bounds.value.y1-y)*bounds.value.scale;</script><template><div class="survey-plot"><div class="plot-title"><strong>{{title||'局部米制平面'}}</strong><span>x/y同一比例 · local_m · 米</span></div><div class="boundary-legend"><label><input type="checkbox" v-model="showPoints" aria-label="显示原始点"/><i class="point-key"/>原始点 {{points.length}}</label><label v-if="result"><input type="checkbox" v-model="showHull" aria-label="显示凸包"/><i class="hull-key"/>凸包</label><label v-if="result"><input type="checkbox" v-model="showAxis" aria-label="显示轴框"/><i class="axis-key"/>轴对齐框</label><label v-if="result"><input type="checkbox" v-model="showBox" aria-label="显示定向框"/><i class="box-key"/>最小定向框</label></div><svg viewBox="0 0 1000 490" role="img" aria-label="真实比例米制足迹与包络"><g v-for="f in [0,.25,.5,.75,1]" :key="f"><line :x1="sx(bounds.x0)" :x2="sx(bounds.x1)" :y1="sy(bounds.y0+f*(bounds.y1-bounds.y0))" :y2="sy(bounds.y0+f*(bounds.y1-bounds.y0))" stroke="#d8d0bb"/><line :x1="sx(bounds.x0+f*(bounds.x1-bounds.x0))" :x2="sx(bounds.x0+f*(bounds.x1-bounds.x0))" :y1="sy(bounds.y0)" :y2="sy(bounds.y1)" stroke="#e2dccb"/><text :x="sx(bounds.x0)-9" :y="sy(bounds.y0+f*(bounds.y1-bounds.y0))+4" text-anchor="end">{{num(bounds.y0+f*(bounds.y1-bounds.y0),2)}}</text><text :x="sx(bounds.x0+f*(bounds.x1-bounds.x0))" :y="sy(bounds.y0)+22" text-anchor="middle">{{num(bounds.x0+f*(bounds.x1-bounds.x0),2)}}</text></g><BoundaryShape v-if="result&&showAxis" :geometry="result.axis_box" color="#98998d" :sx="sx" :sy="sy" dashed :radius="12"/><BoundaryShape v-if="result&&showHull" :geometry="result.hull" color="#b69b4f" :sx="sx" :sy="sy" :radius="7"/><BoundaryShape v-if="result&&showBox" :geometry="result.oriented_box" color="#a96e48" :sx="sx" :sy="sy" :radius="16"/><g v-if="showPoints"><circle v-for="p in points" :key="p.point_id" :cx="sx(p.x)" :cy="sy(p.y)" r="2.8" fill="#52665b" opacity=".7"><title>{{p.point_id}} · x={{p.x}}m / y={{p.y}}m</title></circle></g><text :x="sx(bounds.x0)" y="18">y / 米</text><text :x="sx(bounds.x1)" :y="sy(bounds.y0)+46" text-anchor="end">x / 米</text></svg><p class="muted" v-if="!compact">视窗留白仅用于显示，x/y缩放严格一致；点/线模式不生成填充面，凸包填凹口不代表真实覆盖。</p></div></template>